def _detach(value):
    t = type(value)
    if t is dict:
        return {key: _detach(item) for key, item in value.items()}
    if t is list:
        return [_detach(item) for item in value]
    if t is tuple:
        return tuple(_detach(item) for item in value)
    if t is set:
        return set(value)
    if t is frozenset:
        return value
    if isinstance(value, (dict, list, tuple, set)):
        return copy.deepcopy(value)
    return value


